# Generated by manage.py generate_test_cases.
from django.core.exceptions import ValidationError

from bloomerp.models.communication.instant_messaging.im_connection import IMConnection
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)


class TestImconnectionModel(BloomerpModelTestCase):
    """Allow configured external accounts without an internal connection record."""

    model = IMConnection

    def get_test_scenarios(self) -> list[ModelScenario[IMConnection]]:
        """Reject internal and unknown providers in connection configuration."""
        return [
            ModelScenario(
                name="Reject internal connection",
                create_args={"name": "Internal", "provider": "internal"},
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="External connection",
                create_args={"name": "Sales", "provider": "whatsapp"},
            ),
            ModelScenario(
                name="Reject unknown provider",
                create_args={"name": "Unknown", "provider": "missing"},
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
        ]
